@[export:'rodinia_streamcluster_pgain']
pub fn rodinia_streamcluster_pgain(values &i64,length usize,mut output &u8,capacity usize)i64{unsafe{if values==nil||length<5||length>53{return -1};pn:=values[0];dd:=values[1];xx:=values[2];z:=values[3];mask:=values[4];if pn<2||pn>8||dd<1||dd>3||length!=usize(5+pn*(3+dd))||xx<0||xx>=pn||z<1||z>64||mask<=0||(u64(mask)>=(u64(1)<<u32(pn)))||(mask&(i64(1)<<u32(xx)))!=0{return -1};p:=int(pn);d:=int(dd);x:=int(xx);mut q:=5;mut a:=[8]int{};mut w:=[8]i64{};mut c:=[8]i64{};mut pt:=[8][3]i64{};for i in 0..p{if values[q]<0||values[q]>=pn{return -1};a[i]=int(values[q]);q++;if mask&(i64(1)<<u32(a[i]))==0{return -1}};for i in 0..p{if values[q]<1||values[q]>4{return -1};w[i]=values[q];q++};for i in 0..p{c[i]=values[q];q++};for i in 0..p{for k in 0..d{if values[q] < -8||values[q]>8{return -1};pt[i][k]=values[q];q++}};for i in 0..p{mut ds:=i64(0);for k in 0..d{t:=pt[i][k]-pt[a[i]][k];ds+=t*t};if c[i]!=w[i]*ds||(mask&(i64(1)<<u32(i))!=0&&(a[i]!=i||c[i]!=0)){return -1}};mut sw:=[8]bool{};mut low:=[8]i64{};mut cl:=[8]bool{};mut opening:=z;for i in 0..p{mut ds:=i64(0);for k in 0..d{t:=pt[i][k]-pt[x][k];ds+=t*t};xc:=w[i]*ds;if xc<c[i]{sw[i]=true;opening+=xc-c[i]}else{low[a[i]]+=c[i]-xc}};for j in 0..p{if mask&(i64(1)<<u32(j))!=0{lo:=z+low[j];if lo>0{cl[j]=true;opening-=lo}}};yes:=opening<0;mut om:=mask;mut oa:=a;mut oc:=c;if yes{for i in 0..p{if sw[i]||cl[a[i]]{mut ds:=i64(0);for k in 0..d{t:=pt[i][k]-pt[x][k];ds+=t*t};oa[i]=x;oc[i]=w[i]*ds}};for j in 0..p{if cl[j]{om&=~(i64(1)<<u32(j))}};om|=i64(1)<<u32(x)};mut count:=i64(0);mut obj:=i64(0);for j in 0..p{if om&(i64(1)<<u32(j))!=0{count++}};obj=count*z;for i in 0..p{obj+=oc[i]};if output==nil||capacity<usize(8*(5+2*p)){return -2};mut r:=[21]i64{};r[0]=if yes{i64(1)}else{i64(0)};r[1]=if yes{-opening}else{i64(0)};r[2]=count;r[3]=om;r[4]=obj;for i in 0..p{r[5+i]=i64(oa[i]);r[5+p+i]=oc[i]};for i in 0..5+2*p{u:=u64(r[i]);for b in 0..8{output[i*8+b]=u8(u>>(8*b))}};return i64(5+2*p)}}
